package com.zpantry.pantry.api;import static com.zpantry.pantry.api.PantryDtos.*;import com.zpantry.common.api.*;import com.zpantry.pantry.service.PantryService;import com.zpantry.user.security.AuthenticatedUserResolver;import java.util.UUID;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/me/pantry")public class PantryController{private final PantryService s;private final AuthenticatedUserResolver ids;public PantryController(PantryService s,AuthenticatedUserResolver i){this.s=s;ids=i;}private UUID id(Authentication a){return ids.resolve(a).orElseThrow().userId();}@GetMapping public PagedResponse<PantryItemResponse>get(Authentication a,@RequestParam(defaultValue="1")int pageIndex,@RequestParam(defaultValue="10")int pageSize){return s.list(id(a),pageIndex,pageSize);}@GetMapping("/items")public PagedResponse<PantryItemResponse>items(Authentication a,@RequestParam(defaultValue="1")int pageIndex,@RequestParam(defaultValue="10")int pageSize){return s.list(id(a),pageIndex,pageSize);}@PostMapping("/items")public ApiResponse<PantryItemResponse>upsert(Authentication a,@RequestBody UpsertPantryItemRequest r){return s.upsert(id(a),r);}@PutMapping("/items/{itemId}")public ApiResponse<PantryItemResponse>update(Authentication a,@PathVariable UUID itemId,@RequestBody UpdatePantryItemRequest r){return s.update(id(a),itemId,r);}@DeleteMapping("/items/{itemId}")public ApiResponse<Object>delete(Authentication a,@PathVariable UUID itemId){return s.delete(id(a),itemId);}}
